<?php $labels=['draft'=>'مسودة','approved'=>'معتمد','cancelled'=>'ملغي'];$isDraft=$certificate['status']==='draft';?>
<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><div class="page-pretitle"><?=e($certificate['subcontract_code'].' - '.$certificate['subcontract_title'])?></div><h2 class="page-title"><?=e($certificate['certificate_code'])?></h2></div><div class="col-auto d-flex gap-2"><a class="btn" href="/subcontracts/<?=(int)$certificate['subcontract_id']?>/certificates">العودة للمستخلصات</a><?php if($isDraft&&$canEdit):?><a class="btn" href="/subcontract-certificates/<?=(int)$certificate['id']?>/edit">تعديل المسودة</a><?php endif;?></div></div></div>
<div class="card mb-4"><div class="card-body"><div class="row g-3"><div class="col-md-3"><div class="text-secondary">الرقم المرجعي</div><strong><?=e($certificate['certificate_number']??'—')?></strong></div><div class="col-md-3"><div class="text-secondary">التاريخ</div><strong><?=e($certificate['certificate_date'])?></strong></div><div class="col-md-3"><div class="text-secondary">الفترة</div><strong><?=e(($certificate['period_from']??'—').' إلى '.($certificate['period_to']??'—'))?></strong></div><div class="col-md-3"><div class="text-secondary">الحالة</div><span class="badge bg-blue-lt"><?=e($labels[$certificate['status']]??$certificate['status'])?></span></div></div></div></div>
<div class="card mb-4"><div class="table-responsive"><table class="table table-vcenter"><thead><tr><th>البند</th><th>النوع</th><th>أساس العقد</th><th>السابق</th><th>الحالي</th><th>التراكمي</th><th>القيمة الحالية</th><th>القيمة التراكمية</th></tr></thead><tbody><?php foreach($items as$item):$lump=$item['pricing_type_snapshot']==='lump_sum';$previous=$isDraft?$item['live_previous_quantity']:($lump?$item['previous_progress_percentage']:$item['previous_quantity']);$current=$lump?$item['current_progress_percentage']:$item['current_quantity'];$cumulative=$isDraft?$item['live_cumulative_quantity']:($lump?$item['cumulative_progress_percentage']:$item['cumulative_quantity']);?><tr><td><?=e($item['description_snapshot'])?></td><td><?=$lump?'مقطوعية':'كمي'?></td><td><?=$lump?decimal_format((string)$item['lump_sum_amount_snapshot']):e((string)$item['contract_quantity'].' '.(string)($item['unit_symbol_snapshot']??''))?></td><td><?=e((string)$previous)?><?=$lump?'%':''?></td><td><?=e((string)$current)?><?=$lump?'%':''?></td><td><?=e((string)$cumulative)?><?=$lump?'%':''?></td><td><?=decimal_format((string)($isDraft?$item['live_current_amount']:$item['current_amount']))?></td><td><?=decimal_format((string)($isDraft?$item['live_cumulative_amount']:$item['cumulative_amount']))?></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="row g-3 mb-4"><?php foreach(['previous_earned_value'=>'القيمة السابقة','current_earned_value'=>'القيمة الحالية','cumulative_earned_value'=>'القيمة التراكمية']as$key=>$label):?><div class="col-md-4"><div class="card card-sm"><div class="card-body"><div class="text-secondary"><?=$label?></div><div class="h2"><?=isset($certificate[$key])?decimal_format((string)$certificate[$key]):'تحسب عند الاعتماد'?></div></div></div></div><?php endforeach;?></div>
<?php if($isDraft):?><div class="d-flex gap-2"><?php if($canApprove):?><form method="post" action="/subcontract-certificates/<?=(int)$certificate['id']?>/approve" class="js-confirm-form"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-success">اعتماد المستخلص</button></form><?php endif;?><?php if($canCancel):?><form method="post" action="/subcontract-certificates/<?=(int)$certificate['id']?>/cancel" class="js-confirm-form"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-danger">إلغاء المسودة</button></form><?php endif;?></div><?php endif;?>
